const { test } = require("node:test");
const assert = require("node:assert/strict");
const { startServer, api } = require("./helpers");

test("item creation is rejected when it would exceed warehouse maxCapacity", async () => {
  const { base, close } = startServer();
  try {
    const w = await api(base, "POST", "/api/warehouses", { name: "W", location: "x", maxCapacity: 10 });
    const ok = await api(base, "POST", "/api/items", {
      sku: "A", name: "A", warehouseId: w.json.id, quantity: 6, reorderThreshold: 0,
    });
    assert.equal(ok.status, 201);

    const overflow = await api(base, "POST", "/api/items", {
      sku: "B", name: "B", warehouseId: w.json.id, quantity: 5, reorderThreshold: 0,
    });
    assert.equal(overflow.status, 400, "6 + 5 = 11 > maxCapacity 10");
  } finally {
    await close();
  }
});

test("IN movement is rejected when it would exceed warehouse maxCapacity", async () => {
  const { base, close } = startServer();
  try {
    const w = await api(base, "POST", "/api/warehouses", { name: "W", location: "x", maxCapacity: 10 });
    const item = await api(base, "POST", "/api/items", {
      sku: "A", name: "A", warehouseId: w.json.id, quantity: 8, reorderThreshold: 0,
    });
    const rejected = await api(base, "POST", `/api/items/${item.json.id}/movements`, {
      type: "IN", quantity: 5,
    });
    assert.equal(rejected.status, 400, "8 + 5 = 13 > maxCapacity 10 - the movement path must enforce capacity too");

    const stillOk = await api(base, "GET", `/api/items/${item.json.id}`);
    assert.equal(stillOk.json.quantity, 8, "rejected movement must not have changed quantity");

    const accepted = await api(base, "POST", `/api/items/${item.json.id}/movements`, {
      type: "IN", quantity: 2,
    });
    assert.equal(accepted.status, 201, "8 + 2 = 10, exactly at capacity, must be allowed");
  } finally {
    await close();
  }
});

